css:
.loader {
  width: 120px;
  height: 120px;
  display: flex;
  flex-wrap: wrap;
  perspective: 1000px;
}

.cube {
  width: 50px;
  height: 50px;
  background: linear-gradient(135deg, #a2c2e6, #e0eafc, #b4b8c1);
  margin: 5px;
  transform-style: preserve-3d;
  animation: rotateCube 1.5s infinite ease-in-out;
  position: relative;
}

.cube::before,
.cube::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: inherit;
  transform-style: preserve-3d;
  transform: rotateX(90deg);
}

@keyframes rotateCube {
  0% {
    transform: rotateX(0deg) rotateY(0deg);
  }
  50% {
    transform: rotateX(180deg) rotateY(180deg);
  }
  100% {
    transform: rotateX(360deg) rotateY(360deg);
  }
}
